/**
 * Lists the Markdown files the corpus check loads into the editor
 * (`npm run corpus:run`), de-duplicated by content so a note copied into
 * several vaults is checked once.
 *
 *   node scripts/corpus/buildList.mjs <out.txt> [--vaults <dir>] [--extra <dir>]...
 *
 * Walks, in this order:
 *   - this repo's own `.md` files (not node_modules, .git, dist, out);
 *   - `--vaults <dir>`: a folder of vaults, skipping each vault's `.filo/`;
 *   - `--extra <dir>` (repeatable): any other folder, e.g. one generated by
 *     `scripts/perf/genVault.mjs`;
 *   - README files in node_modules, two levels deep.
 *
 * Entries are walked in sorted order, so the same folders give the same list.
 * Only reads; writes nothing but the list.
 */
import { createHash } from 'node:crypto';
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const repo = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

function usage(message) {
  if (message) console.error(message);
  console.error('Usage: node scripts/corpus/buildList.mjs <out.txt> [--vaults <dir>] [--extra <dir>]...');
  process.exit(1);
}

function parseArgs(argv) {
  const args = { out: '', vaults: '', extra: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--vaults' || a === '--extra') {
      const dir = argv[++i];
      if (!dir) usage(`${a} needs a folder`);
      const full = resolve(dir);
      // A mistyped folder would otherwise walk nothing and shrink the corpus unnoticed.
      if (!existsSync(full) || !statSync(full).isDirectory()) usage(`Not a folder: ${full}`);
      if (a === '--vaults') args.vaults = full;
      else args.extra.push(full);
    } else if (!args.out) args.out = resolve(a);
    else usage(`Unexpected argument: ${a}`);
  }
  if (!args.out) usage();
  return args;
}

const isMarkdown = (name) => name.toLowerCase().endsWith('.md');
const isReadme = (name) => /^readme.*\.md$/i.test(name);

const seen = new Set();
const files = [];
const counts = {};

function add(path, group) {
  let bytes;
  try {
    bytes = readFileSync(path);
  } catch {
    return; // unreadable (locked, removed mid-walk): not part of this corpus
  }
  const hash = createHash('sha1').update(bytes).digest('hex');
  if (seen.has(hash)) return;
  seen.add(hash);
  files.push(path);
  counts[group] = (counts[group] ?? 0) + 1;
}

function walk(dir, group, { skip, depth = Infinity, match = isMarkdown }) {
  if (depth < 0) return;
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }
  entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  for (const e of entries) {
    const p = join(dir, e.name);
    // Links are neither: a junction or symlink could loop or leave the folder.
    if (e.isDirectory()) {
      if (!skip.includes(e.name)) walk(p, group, { skip, depth: depth - 1, match });
    } else if (e.isFile() && match(e.name)) add(p, group);
  }
}

const args = parseArgs(process.argv.slice(2));
walk(repo, 'repo', { skip: ['node_modules', '.git', 'dist', 'out'] });
if (args.vaults) walk(args.vaults, 'vaults', { skip: ['.filo'] });
for (const dir of args.extra) walk(dir, 'extra', { skip: ['.filo', '.git', 'node_modules'] });
walk(join(repo, 'node_modules'), 'node_modules', { skip: [], depth: 2, match: isReadme });

writeFileSync(args.out, files.join('\n'));
console.log(`${files.length} notes`, counts, `-> ${args.out}`);
